CREATE TABLE canvas_connections (    id UUID PRIMARY KEY,    user_id UUID NOT NULL,    canvas_base_url VARCHAR(512) NOT NULL,    access_token TEXT NOT NULL,    refresh_token TEXT,    token_expires_at TIMESTAMP WITH TIME ZONE,    canvas_user_id VARCHAR(64),    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,    CONSTRAINT uq_canvas_connections_user_id UNIQUE (user_id),    CONSTRAINT fk_canvas_connections_user        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE);CREATE INDEX idx_canvas_connections_user_id ON canvas_connections (user_id);